import 'dart:convert';
import 'dart:io';

import 'package:folia_mobile/monet/monet_motion.dart';
import 'package:folia_mobile/lyrics/lyric_document.dart';

// A minimal port check against values generated by the original TypeScript functions; no UI/emulator.
void main() {
  final data = jsonDecode(
    File('test/fixtures/monet_motion_reference.json').readAsStringSync(),
  ) as Map;
  void close(num a, num b) {
    if ((a - b).abs() > 1e-9) throw StateError('$a != $b');
  }

  for (final sample in data['samples'] as List) {
    close(
      resolveMonetGlow((sample['time'] as num).toDouble(), 1, 2, 4),
      sample['glow'] as num,
    );
    close(
      resolveMonetFillWidth((sample['time'] as num).toDouble(), 1, 2, [
        0,
        12,
        27,
        40,
      ]),
      sample['fill'] as num,
    );
  }
  for (final item in data['tones'] as List) {
    final value = resolveMonetTone(
      item['status'] as String,
      item['offset'] as int,
    );
    close(value.opacity, item['alpha'] as num);
    close(value.scale, item['scale'] as num);
    close(value.blur, item['blur'] as num);
  }
  final lrc = LyricDocument.parse(
    '[offset:100]\n[00:01.00][00:03.00]One\n[00:02.00]Two',
    duration: 5,
  );
  if (lrc.lines.length != 3 ||
      lrc.activeIndex(.5) != -1 ||
      lrc.activeIndex(1.5) != 0 ||
      lrc.activeIndex(3.5) != 2) {
    throw StateError('LRC timing');
  }
  final yrc = LyricDocument.parse('[1000,1200](1000,500,0)你(1500,700,0)好');
  if (yrc.lines.single.text != '你好' || yrc.lines.single.words.last.end != 2.2) {
    throw StateError('YRC timing');
  }
  stdout.writeln('Original Monet envelopes and LRC/YRC checks passed');
}
